contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 seed) public {
        require(seed > 0);
        c.seedMarket(seed); if (__ESBMC_reverted()) return;
        require(!c.initialized() == false);
        bool firstOk;
        c.getFreeKilo(); if (__ESBMC_reverted()) return;
        uint256 kilos = c.getMyKilo(); if (__ESBMC_reverted()) return;
        bool secondReverted;
        c.getFreeKilo(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { secondReverted = true; } else { secondReverted = false; }
        assert(kilos == c.STARTING_KILOS() && secondReverted);
    }
    receive() external payable {}
}

