// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherCartel c;

    function setUp() public {
        c = new EtherCartel();
    }

    function _run(uint256 seed) internal {
        vm.assume(seed > 0);
        try c.seedMarket(seed) {} catch { return; }
        vm.assume(!c.initialized() == false);
        bool firstOk;
        try c.getFreeKilo() {} catch { return; }
        uint256 kilos;
        try c.getMyKilo() returns (uint256 __r) { kilos = __r; } catch { return; }
        bool secondReverted;
        try c.getFreeKilo() { secondReverted = false; } catch { secondReverted = true; }
        assertTrue(kilos == c.STARTING_KILOS() && secondReverted);
    }

    function testFuzz_run(uint256 seed) public {
        _run(seed);
    }

    receive() external payable {}
}
